item.stdout:
{"connection_id": "BC-f929c0809eacaf97d1e2", "ref": "SBLGNT:Luke.14.14", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "repayment at resurrection", "note": "The host who cannot be repaid now will be repaid at the resurrection of the righteous; it connects selfless preference with a future reward instead of worldly return."}
{"connection_id": "BC-ada7cea4ba876e5214e5", "ref": "SBLGNT:Luke.14.14", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "repayment at righteous resurrection", "note": "Because such guests cannot repay, God repays the host at the resurrection of the righteous; generosity is explicitly joined to the lasting future."}
{"connection_id": "BC-cf39bd50993ca9f898d1", "ref": "SBLGNT:Luke.16.25", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "reversal after death", "note": "Abraham tells the rich man he received good things in life while Lazarus received bad, but now Lazarus is comforted and he is in anguish; this is a concrete reversal of worldly valuation in the afterlife."}
{"connection_id": "BC-1dfd08fb9af042819bf1", "ref": "SBLGNT:Luke.16.25", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "rich man's good things / Lazarus's comfort", "note": "Abraham recalls that the rich man received good things in life while Lazarus received bad, but their postmortem conditions are reversed; it tests what worldly “good” is worth."}
{"connection_id": "BC-972ca64ca36ad2452d38", "ref": "SBLGNT:Luke.3.17", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "wheat and chaff at judgment", "note": "Luke’s parallel report likewise gathers wheat and burns chaff; its own version makes the commentary’s sorting of selected and discarded outcomes eschatological."}
{"connection_id": "BC-38c03c4daf01e45ff038", "ref": "SBLGNT:Mark.10.29", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "leaving goods for the gospel", "note": "Jesus promises recognition to those who leave house, kin, or lands for him and the gospel; this gives a concrete cost to choosing the enduring good over present attachments."}
{"connection_id": "BC-fc51f84a309afb1f7583", "ref": "SBLGNT:Mark.10.30", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "eternal life in the coming age", "note": "The promise culminates in eternal life in the coming age; this supplies the lasting outcome that frames the worldly losses of the preceding verse."}
{"connection_id": "BC-a7db2f85cefac79b1be3", "ref": "SBLGNT:Mark.8.36", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "gain the world, lose life", "note": "Jesus asks what profit it is to gain the whole world and forfeit one’s life; this directly rebukes the preference for worldly life in 87:16."}
{"connection_id": "BC-c22d1f52a163f4f6d315", "ref": "SBLGNT:Mark.8.36", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "whole world / forfeited life", "note": "The question about gaining the whole world while forfeiting one's life concentrates worldly acquisition and ultimate loss into the commentary's two-sided valuation."}
{"connection_id": "BC-16cd9e5868b9a54dda49", "ref": "SBLGNT:Matt.13.22", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "wealth's deceit chokes the word", "note": "The worry of the age and deceitfulness of wealth choke the word and make it fruitless, a specific New Testament account of worldly preference producing spiritual waste."}
{"connection_id": "BC-7e1fae7f36344ef97abc", "ref": "SBLGNT:Matt.13.30", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "weeds gathered for burning", "note": "At harvest the weeds are gathered and burned while wheat is stored; the parable gives the commentary’s “selection” a concrete scene of separating what is retained from what is discarded."}
{"connection_id": "BC-d1353fc63d7c09b5da7f", "ref": "SBLGNT:Matt.13.48", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "good fish and bad fish", "note": "The net’s good fish are kept in vessels and the bad thrown away; this closely matches the commentary’s selected, dreg-free lot versus discarded residue."}
{"connection_id": "BC-8bdcd5581055b88b7cb7", "ref": "SBLGNT:Matt.13.48", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "good fish collected, bad thrown out", "note": "In the net parable, fish are sorted: the good are collected into containers and the bad thrown outside. It is a precise sorting image for selected good and rejected refuse."}
{"connection_id": "BC-2b198f1f788391d03cfe", "ref": "SBLGNT:Matt.13.49", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "angels separate wicked from righteous", "note": "Jesus explains the net as a final separation of the evil from the righteous, giving the preceding culling image an explicitly eschatological value judgment."}
{"connection_id": "BC-b176a30e7c7051942172", "ref": "SBLGNT:Matt.19.21", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "treasure in heaven over possessions", "note": "Jesus tells the rich inquirer to sell his possessions, give to the poor, and follow him for treasure in heaven; this makes the better, lasting choice costly and relational."}
{"connection_id": "BC-60534ab838ebf34da6f6", "ref": "SBLGNT:Matt.19.21", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "giving possessions / treasure in heaven", "note": "Jesus tells the rich man to give his possessions to the poor and have treasure in heaven, turning a costly redistribution into an enduring treasure."}
{"connection_id": "BC-aafcfdf1b44d22de67f4", "ref": "SBLGNT:Matt.19.22", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "wealth prevents the choice", "note": "The inquirer leaves grieving because he has many possessions; the narrative concretely shows worldly wealth winning out over the offered lasting good."}
{"connection_id": "BC-645e3d54403ba0842c64", "ref": "SBLGNT:Matt.25.32", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "sheep separated from goats", "note": "The Son of Man separates all nations as a shepherd separates sheep and goats; this makes the commentary’s two lots a final moral sorting of people."}
{"connection_id": "BC-dcc90f8af66672d1d730", "ref": "SBLGNT:Matt.25.40", "target": "sec16", "tradition": "incil", "kind": "motif", "basis": "service to the least and the kingdom", "note": "The king identifies care for the least with service to himself; in the scene’s inheritance of the kingdom, this makes the commentary’s giving priority to another an act with lasting consequence."}
{"connection_id": "BC-b3aad0f96c2b45f2dd68", "ref": "SBLGNT:Matt.25.40", "target": "sec16", "tradition": "incil", "kind": "karsi_anlati", "basis": "the least identified with the king", "note": "Care given to the least of the king's brothers is counted as care given to the king himself, reversing any association of socially low people with discardable material."}

