item.stdout:
{"connection_id": "BC-49eb497ab15cfdd7f473", "ref": "Mishnah Avot 6:9", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "what accompanies a person at death", "note": "The teaching says silver, gold, and precious stones do not accompany a person at death, while Torah and good deeds do; it sharply distinguishes temporary possession from what remains."}
{"connection_id": "BC-2d0b88fae94c0f41d8f8", "ref": "Mishnah Peah 1:1", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "this-world fruit and future principal", "note": "The Mishnah says loving-kindness and honoring parents yield fruit in this world while their principal remains for the world to come; its opening discussion of field-corner gleanings also makes a deliberately retained remnant fruitful rather than refuse."}
{"connection_id": "BC-7f8a12a480039440b81c", "ref": "Mishnah Peah 1:1", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "fruits now / principal remaining", "note": "The mishnah names deeds whose fruits are enjoyed now while their principal remains for the world to come, a precise Jewish account of good that remains."}
{"connection_id": "BC-b673d28b26f5e3a4cac0", "ref": "Sirach 40:17", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "almsgiving endures forever", "note": "Sirach calls kindness a blessed garden and says almsgiving endures forever, joining the commentary's remaining goodness to generosity rather than accumulation."}
{"connection_id": "BC-cc688568ffeac9dadc57", "ref": "Tobit 4:9", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "almsgiving as good treasure", "note": "Tobit's father says almsgiving lays up a good treasure for the day of need, a Jewish exhortation to turn possessions into a durable good through giving."}
{"connection_id": "BC-b73eb2c58254308a311a", "ref": "WLC:1Kgs.19.18", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "remnant that did not bow", "note": "God preserves seven thousand who have not bowed to Baal; the faithful remnant gives a concrete Jewish-scriptural instance of the commentary’s people retaining their religion."}
{"connection_id": "BC-b860e30a6ee1428ae32d", "ref": "WLC:1Kgs.19.18", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "seven thousand preserved", "note": "God leaves seven thousand who have not bowed to Baal, a surviving moral remnant that resists corruption as the commentary's baqiyya image does."}
{"connection_id": "BC-22d6421f8f0daf5e2586", "ref": "WLC:1Kgs.3.11", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "Solomon's requested discernment", "note": "Solomon does not ask for long life, riches, or enemies' lives, but discernment for justice; his choice gives a narrative instance of seeking a higher good."}
{"connection_id": "BC-96c7bf8c1787ddc16c2e", "ref": "WLC:1Sam.16.7", "target": "sec16", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "appearance versus heart", "note": "God rejects human sight of outward appearance and looks at the heart; it reframes the commentary's language of low value and selection around hidden moral reality."}
{"connection_id": "BC-9b6dffb84a1e0e8b713a", "ref": "WLC:Amos.5.15", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "remnant seeking good and justice", "note": "Amos tells Israel to hate evil, love good, and establish justice, with the hope that God may be gracious to Joseph’s remnant; this concretizes the commentary’s bakiyya as a moral remainder holding to goodness."}
{"connection_id": "BC-fe8dc7524107474b086c", "ref": "WLC:Dan.12.2", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "everlasting life or contempt", "note": "Daniel’s sleepers awake to everlasting life or everlasting disgrace; this directly supplies divergent lasting outcomes for the commentary’s better afterlife."}
{"connection_id": "BC-f4ecb78263b9b0b3022d", "ref": "WLC:Dan.12.2", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "everlasting life / everlasting contempt", "note": "Those awakening from the dust receive either everlasting life or everlasting abhorrence, furnishing both the enduring good and the enduring adverse fate developed in the commentary."}
{"connection_id": "BC-f313d647f561c27cb23d", "ref": "WLC:Dan.3.18", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "refusal despite the furnace", "note": "The three Judeans say they will not serve the king’s gods even if God does not rescue them; this is another concrete choice of fidelity over threatened present life, like the magicians in the commentary’s cited Qur’anic scene."}
{"connection_id": "BC-34204e297fa3490ce6c7", "ref": "WLC:Dan.3.18", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "refusal before a king", "note": "The Judean officials refuse the king's gods and image even if God does not rescue them; like the commentary's magicians before Pharaoh, they choose fidelity under royal threat."}
{"connection_id": "BC-dc4dfda34837825b3c91", "ref": "WLC:Deut.24.19", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "forgotten sheaf left for the vulnerable", "note": "Israel must leave a forgotten sheaf for the immigrant, orphan, and widow; what is accidentally left behind becomes provision for low-status people, qualifying the commentary’s image of discarded residue as worthless."}
