item.stdout:
{"connection_id": "BC-a07dc394aa45fcf6f446", "ref": "WLC:Deut.31.21", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "song not forgotten", "note": "The song will not be forgotten from descendants’ mouths even amid calamity; this is a concrete scriptural counterpoint to 87:6’s promise that the prophet will not forget recitation."}
{"connection_id": "BC-5c1fdaa2c2bbfd66f6a1", "ref": "WLC:Deut.32.15", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "prosperity and forsaking God", "note": "Jeshurun grows fat, abandons the God who made him, and despises the Rock of salvation; it gives worldly abundance the same spiritual danger as the commentary's preference for dunya."}
{"connection_id": "BC-9187950d6aa3f759c3dc", "ref": "WLC:Deut.7.7", "target": "sec16", "tradition": "tevrat", "kind": "karsi_anlati", "basis": "chosen despite being few", "note": "Israel is chosen not for numerical abundance but despite being the fewest people, offering a counterpoint to reading selectness through quantity or social rank."}
{"connection_id": "BC-4f1c2c8a6ae798253c82", "ref": "WLC:Deut.8.14", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "prosperity and forgetting God", "note": "After prosperity lifts the heart, Israel may forget the LORD; this supplies a concrete biblical form of the commentary's worldly preference joined to forgetting."}
{"connection_id": "BC-059edacc8932688e0b0c", "ref": "WLC:Eccl.12.7", "target": "sec16", "tradition": "tevrat", "kind": "motif", "basis": "dust returning / spirit returning", "note": "At death dust returns to earth and the spirit returns to God who gave it; it offers a restrained biblical account of bodily transience beside a Godward remainder."}
