text(await tools.apply_patch("*** Begin Patch
*** Update File: /Volumes/aro/projects/prose_generation/enrichment/bible/work/s087/ehlikitap-images.sol.max.session-20261005/sec16/verdicts.jsonl
@@
 {"connection_id":"BC-2844dd0af6d0d7a33942","ref":"SBLGNT:Acts.5.29","status":"rejected","reason":"Obedience to God rather than humans is relevant to threatened allegiance, but Exodus 1:17 gives a closer Pharaoh-specific instance.","paragraphs":[],"evidence":["SBLGNT:Acts.5.29"],"annotations":[]}
+{"connection_id":"BC-93120629be29b873f68c","ref":"SBLGNT:Acts.5.29","status":"rejected","reason":"The apostles' authority conflict lacks the specific worldly-life and future-good contrast; the annotated midwives and Moses passages fit paragraph 64 more closely.","paragraphs":[],"evidence":["SBLGNT:Acts.5.29"],"annotations":[]}
+{"connection_id":"BC-00acf308717541417428","ref":"SBLGNT:Col.3.1","status":"rejected","reason":"Seeking things above is grounded in being raised with Christ; it adds less to this section's better-and-abiding comparison than Hebrews 10:34.","paragraphs":[],"evidence":["SBLGNT:Col.3.1"],"annotations":[]}
+{"connection_id":"BC-8e3526a30ca720daede9","ref":"SBLGNT:Col.3.2","status":"rejected","reason":"The above/earth contrast is spatial and does not itself state permanence or a concrete costly preference.","paragraphs":[],"evidence":["SBLGNT:Col.3.2"],"annotations":[]}
+{"connection_id":"BC-ca75027f55dca5f85e64","ref":"SBLGNT:Gal.6.8","status":"rejected","reason":"Sowing flesh or Spirit yields corruption or eternal life, but its harvest image is less close to the selected refuse than Psalm 1 and Matthew 3.","paragraphs":[],"evidence":["SBLGNT:Gal.6.8"],"annotations":[]}
+{"connection_id":"BC-a1fdc9012b78bbfbda8b","ref":"SBLGNT:Heb.10.34","status":"accepted","reason":"Confiscated property is weighed against a possession explicitly called better and abiding.","paragraphs":[61],"evidence":["SBLGNT:Heb.10.34"],"annotations":["S087-INC-MTF-001"]}
+{"connection_id":"BC-708081dab2e321199014","ref":"SBLGNT:Heb.10.34","status":"accepted","reason":"The Greek pairs kreittona and menousan in a threatened loss of worldly goods, matching the paragraph's two terms.","paragraphs":[61],"evidence":["SBLGNT:Heb.10.34"],"annotations":["S087-INC-MTF-001"]}
+{"connection_id":"BC-38f211d47897f082b05e","ref":"SBLGNT:Heb.11.25","status":"accepted","reason":"Moses explicitly chooses suffering with God's people over temporary pleasure.","paragraphs":[64],"evidence":["SBLGNT:Heb.11.25","SBLGNT:Heb.11.26","SBLGNT:Heb.11.35"],"annotations":["S087-INC-MTF-010"]}
+{"connection_id":"BC-453d5921a0a70e115131","ref":"SBLGNT:Heb.11.25","status":"accepted","reason":"The verb of choosing and temporary enjoyment give a direct action counterpart to the commentary's selection.","paragraphs":[64],"evidence":["SBLGNT:Heb.11.25","SBLGNT:Heb.11.26","SBLGNT:Heb.11.35"],"annotations":["S087-INC-MTF-010"]}
+{"connection_id":"BC-0e1fe0cfbf51729d8a86","ref":"SBLGNT:Heb.11.26","status":"accepted","reason":"Egypt's treasure is evaluated below future reward in the Christian Moses reading.","paragraphs":[64],"evidence":["SBLGNT:Heb.11.25","SBLGNT:Heb.11.26","SBLGNT:Heb.11.35"],"annotations":["S087-INC-MTF-010"]}
+{"connection_id":"BC-01c4473a553783c724ee","ref":"SBLGNT:Heb.11.26","status":"accepted","reason":"The explicit Egypt comparison and expected reward sharpen the Moses/Pharaoh setting of paragraph 64.","paragraphs":[64],"evidence":["SBLGNT:Heb.11.25","SBLGNT:Heb.11.26","SBLGNT:Heb.11.35"],"annotations":["S087-INC-MTF-010"]}
+{"connection_id":"BC-6f3b640ad1fa203077f0","ref":"SBLGNT:Heb.11.35","status":"accepted","reason":"The tortured witnesses refuse release for a better resurrection, a concrete costly future-directed choice.","paragraphs":[64],"evidence":["SBLGNT:Heb.11.25","SBLGNT:Heb.11.26","SBLGNT:Heb.11.35"],"annotations":["S087-INC-MTF-010"]}
+{"connection_id":"BC-ccaaa3a2615443034b02","ref":"SBLGNT:Heb.11.35","status":"accepted","reason":"The Greek explicitly says they declined release to obtain a better resurrection; the annotation keeps this point.","paragraphs":[64],"evidence":["SBLGNT:Heb.11.25","SBLGNT:Heb.11.26","SBLGNT:Heb.11.35"],"annotations":["S087-INC-MTF-010"]}
+{"connection_id":"BC-c7fea4f24dabe1e60510","ref":"SBLGNT:Heb.12.16","status":"rejected","reason":"Esau's meal-for-birthright choice concerns inherited status, not the afterlife; it is a more remote preference than the Moses examples.","paragraphs":[],"evidence":["SBLGNT:Heb.12.16"],"annotations":[]}
+{"connection_id":"BC-4be7fcf119e65605591e","ref":"SBLGNT:Heb.12.16","status":"rejected","reason":"The Christian censure of Esau is genuine, but the one-meal exchange has no explicit enduring good or world-to-come horizon.","paragraphs":[],"evidence":["SBLGNT:Heb.12.16"],"annotations":[]}
