+{"connection_id":"BC-d0c5072c652ae530e839","ref":"Mishnah Avot 4:17","status":"unavailable","reason":"No local Avot witness is present to verify the proposed counterweight of present repentance and deeds.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-49eb497ab15cfdd7f473","ref":"Mishnah Avot 6:9","status":"unavailable","reason":"Avot is absent locally; what accompanies a person at death cannot be checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-2d0b88fae94c0f41d8f8","ref":"Mishnah Peah 1:1","status":"unavailable","reason":"Peah is absent locally; the fruit/principal and gleaning associations cannot be checked.","paragraphs":[],"evidence":[],"annotations":[]}
+{"connection_id":"BC-7f8a12a480039440b81c","ref":"Mishnah Peah 1:1","status":"unavailable","reason":"No local Peah witness is present to verify the present-fruit/future-principal maxim.","paragraphs":[],"evidence":[],"annotations":[]}
